"""
Pre-rendered audio fillers to mask latency during LLM/TTS processing.
Generated using ai4bharat/indic-parler-tts — same voice as Priya.
"""
import random
import base64

FILLER_0 = base64.b64decode("")

FILLER_1 = base64.b64decode("")

FILLER_2 = base64.b64decode("")

FILLERS = [f for f in [
    # FILLER_0, # Excluded due to excessive length (~18s)
    FILLER_1,
    FILLER_2,
] if f]

def get_random_filler() -> bytes:
    """Return a random pre-rendered filler clip as raw 24kHz PCM16 bytes."""
    if not FILLERS:
        return b""
    return random.choice(FILLERS)
